// Audit helper mindset: enumerate what the webview may ask for.
#[derive(Debug)]
enum Allowed {
    CoreEvents,
    AppCommands,
}

fn audit(request: &str) -> Option<Allowed> {
    match request {
        "listen" | "emit" => Some(Allowed::CoreEvents),
        "run_rust_code" | "save_note" | "get_bootstrap" => Some(Allowed::AppCommands),
        "fs.read" | "shell.open" => None, // NOT granted — rejected by capability layer
        _ => None,
    }
}

fn main() {
    for req in ["emit", "run_rust_code", "shell.open"] {
        println!("{req}: {:?}", audit(req));
    }
}

