const ALLOWED: [&str; 3] = ["core", "ping", "save_note"];

fn granted(cmd: &str) -> bool {
    ALLOWED.contains(&cmd)
}

fn main() {
    for cmd in ["core", "shell.open", "save_note"] {
        println!("{cmd}: {}", granted(cmd));
    }
}
